dashboard.definition:
{
    "title": "Cisco Meraki",
    "description": "Cisco Meraki assurance alerts, SD-WAN and inventory",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Time range",
            "options": {
                "token": "global_time",
                "defaultValue": "-60m@m,now"
            }
        },
        "input_site": {
            "type": "input.dropdown",
            "title": "Site",
            "options": {
                "items": [
                    {
                        "label": "All sites",
                        "value": "*"
                    },
                    {
                        "label": "Atlanta",
                        "value": "atlanta"
                    },
                    {
                        "label": "Berlin",
                        "value": "berlin"
                    },
                    {
                        "label": "Vienna",
                        "value": "vienna"
                    }
                ],
                "token": "site",
                "defaultValue": "*"
            }
        },
        "input_severity": {
            "type": "input.dropdown",
            "title": "Severity",
            "options": {
                "items": [
                    {
                        "label": "All severities",
                        "value": "*"
                    },
                    {
                        "label": "Critical",
                        "value": "critical"
                    },
                    {
                        "label": "Medium",
                        "value": "medium"
                    },
                    {
                        "label": "Informational",
                        "value": "informational"
                    }
                ],
                "token": "severity",
                "defaultValue": "*"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        },
        "tokens": {
            "default": {
                "severity": {
                    "value": "*"
                },
                "network": {
                    "value": "*"
                }
            }
        }
    },
    "dataSources": {
        "ds_alerts": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_cisco_meraki sourcetype=\"meraki:assurancealerts\"\n| rex field=network.name \"(?i)^(?<mer_site>vienna|berlin|atlanta)\"\n| eval site=lower(mer_site), network='network.name'\n| search site=\"$site$\"\n| bin _time span=5m\n| stats count by _time site network severity categoryType alertType",
                "enableSmartSources": true
            },
            "name": "Assurance alerts (5 min)"
        },
        "ds_k_networks": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_cisco_meraki sourcetype=\"meraki:organizationsnetworks\"\n| rex field=name \"(?i)^(?<mer_site>vienna|berlin|atlanta)\"\n| eval site=lower(mer_site)\n| search site=\"$site$\"\n| stats dc(name) as Networks",
                "enableSmartSources": true
            },
            "name": "Managed networks"
        },
        "ds_k_crit": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_alerts",
                "query": "| where severity=\"critical\" | timechart span=5m sum(count) as Critical"
            }
        },
        "ds_k_warn": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_alerts",
                "query": "| where severity=\"medium\" | timechart span=5m sum(count) as Medium"
            }
        },
        "ds_k_info": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_alerts",
                "query": "| where severity=\"informational\" | timechart span=5m sum(count) as Informational"
            }
        },
        "ds_k_types": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_alerts",
                "query": "| stats dc(alertType) as Types"
            }
        },
        "ds_heat": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_alerts",
                "query": "| search severity=\"$severity$\" | timechart span=5m limit=0 sum(count) by network"
            }
        },
        "ds_timeline": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_alerts",
                "query": "| search network=\"$network$\" | timechart span=5m sum(count) by severity"
            }
        },
        "ds_category": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_alerts",
                "query": "| search severity=\"$severity$\" network=\"$network$\" | stats sum(count) as Alerts by categoryType | sort - Alerts"
            }
        },
        "ds_types": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_alerts",
                "query": "| search severity=\"$severity$\" network=\"$network$\" | stats sum(count) as Alerts by alertType | sort - Alerts | head 10"
            }
        },
        "ds_summary": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_alerts",
                "query": "| stats sum(count) as Total sum(eval(if(severity=\"critical\", count, 0))) as Critical sum(eval(if(severity=\"medium\", count, 0))) as Medium sum(eval(if(severity=\"informational\", count, 0))) as Info dc(alertType) as Types by site network\n| sort - Critical\n| rename site as Site network as Network"
            }
        },
        "ds_detail": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_cisco_meraki sourcetype=\"meraki:assurancealerts\" severity=\"$severity$\"\n| rex field=network.name \"(?i)^(?<mer_site>vienna|berlin|atlanta)\"\n| eval site=lower(mer_site), network='network.name'\n| search site=\"$site$\" network=\"$network$\"\n| head 50\n| eval Time=strftime(_time, \"%H:%M:%S\")\n| table Time site network categoryType severity alertType description\n| rename site as Site network as Network categoryType as Category severity as Severity alertType as \"Alert type\" description as Description",
                "enableSmartSources": true
            },
            "name": "Alert detail"
        },
        "ds_sdwan": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_cisco_meraki sourcetype=\"meraki:assurancealerts\" categoryType=connectivity alertType IN (\"high_latency\", \"packet_loss\", \"uplink_jitter\", \"uplink_failover\", \"vpn_tunnel_degraded\", \"uplink_loss\", \"vpn_tunnel_down\")\n| rex field=network.name \"(?i)^(?<mer_site>vienna|berlin|atlanta)\"\n| eval site=lower(mer_site)\n| search site=\"$site$\"\n| timechart span=5m count by alertType",
                "enableSmartSources": true
            },
            "name": "SD-WAN uplink alerts"
        },
        "ds_mx": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_cisco_meraki sourcetype=\"meraki:devicesavailabilitieschangehistory\" \"device.model\"=\"MX*\" \"details.new{}.name\" IN (\"activeUplink\", \"connectivity\")\n| rex field=network.name \"(?i)^(?<mer_site>vienna|berlin|atlanta)\"\n| eval site=lower(mer_site)\n| search site=\"$site$\"\n| eval change=mvindex('details.new{}.name', 0).\": \".mvindex('details.old{}.value', 0).\" → \".mvindex('details.new{}.value', 0)\n| stats latest(_time) as last count as Changes latest(change) as \"Last change\" by network.name device.name\n| eval \"Last seen\"=strftime(last, \"%H:%M:%S\")\n| sort - Changes\n| table network.name device.name Changes \"Last change\" \"Last seen\"\n| rename network.name as Network device.name as Device",
                "enableSmartSources": true
            },
            "name": "MX uplink changes"
        },
        "ds_inventory": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_cisco_meraki sourcetype=\"meraki:organizationsnetworks\"\n| rex field=name \"(?i)^(?<mer_site>vienna|berlin|atlanta)\"\n| eval site=lower(mer_site)\n| search site=\"$site$\"\n| stats latest(id) as id latest(timeZone) as tz latest(notes) as notes by site name\n| eval Type=case(match(name, \"Corporate\"), \"Corporate\", match(name, \"Factory\"), \"Factory\", match(name, \"Guest\"), \"Guest\", true(), \"Other\")\n| table site name Type tz id notes\n| rename site as Site name as Network tz as Timezone id as \"Network ID\" notes as Notes",
                "enableSmartSources": true
            },
            "name": "Network inventory"
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/coolashaker_studio/images/nav_home.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "coolashaker_studio",
                        "dashboard": "cs_home",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_exec": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/coolashaker_studio/images/nav_exec.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
