        "viz_01": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_networks"
            },
            "options": {
                "majorColor": "#60a5fa",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            }
        },
        "viz_02": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_crit"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 1,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 1,
                        "to": 3,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 3,
                        "value": "#ff4d6d"
                    }
                ]
            }
        },
        "viz_03": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_warn"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 4,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 4,
                        "to": 9,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 9,
                        "value": "#ff4d6d"
                    }
                ]
            }
        },
        "viz_04": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_info"
            },
            "options": {
                "majorColor": "#60a5fa",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            }
        },
        "viz_05": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_types"
            },
            "options": {
                "majorColor": "#a78bfa",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            }
        },
        "viz_06": {
            "type": "coolashaker_studio.heat_timeline",
            "dataSources": {
                "primary": "ds_heat"
            },
            "options": {
                "scaleMode": "relative",
                "decimals": 0,
                "drilldownToken": "network"
            },
            "eventHandlers": [
                {
                    "type": "drilldown.setToken",
                    "options": {
                        "tokens": [
                            {
                                "token": "network",
                                "key": "value"
                            }
                        ]
                    }
                }
            ]
        },
        "viz_07": {
            "type": "splunk.area",
            "dataSources": {
                "primary": "ds_timeline"
            },
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#ff4d6d",
                    "#60a5fa",
                    "#ffb020"
                ],
                "stackMode": "stacked",
                "areaOpacity": 0.35
            }
        },
        "viz_08": {
            "type": "splunk.pie",
            "dataSources": {
                "primary": "ds_category"
            },
            "options": {
                "backgroundColor": "transparent",
                "labelDisplay": "valuesAndPercentage",
                "seriesColors": [
                    "#22d3ee",
                    "#a78bfa",
                    "#34e2a0",
                    "#ffc53d",
                    "#ff4d6d",
                    "#60a5fa",
                    "#f472b6",
                    "#2dd4bf",
                    "#fb923c",
                    "#e879f9"
                ],
                "showDonutHole": true
            }
        },
        "viz_09": {
            "type": "splunk.bar",
            "dataSources": {
                "primary": "ds_types"
            },
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "off",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#60a5fa"
                ]
            }
        },
        "viz_10": {
            "type": "splunk.table",
            "dataSources": {
                "primary": "ds_summary"
            },
            "options": {
                "backgroundColor": "transparent",
                "count": 8,
                "headerVisibility": "fixed",
                "fontSize": "small",
                "tableFormat": {
                    "rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBg)",
                    "headerBackgroundColor": "#0b1630",
                    "rowColors": "#eaf2ff",
                    "headerColor": "#9fb1c9"
                },
                "columnFormat": {
                    "Critical": {
                        "rowBackgroundColors": "> table | seriesByName(\"Critical\") | rangeValue(range_2)"
                    },
                    "Medium": {
                        "rowBackgroundColors": "> table | seriesByName(\"Medium\") | rangeValue(range_3)"
                    }
                }
            },
            "context": {
                "rowBg": [
                    "#0a1328",
                    "#0d1833"
                ],
                "statusBg": [
                    {
                        "match": "Critical",
                        "value": "#5a1426"
                    },
                    {
                        "match": "Degraded",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "Healthy",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "critical",
                        "value": "#5a1426"
                    },
                    {
                        "match": "high",
                        "value": "#5a1426"
                    },
                    {
                        "match": "error",
                        "value": "#5a1426"
                    },
                    {
                        "match": "warning",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "medium",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "stopped",
                        "value": "#5a1426"
                    },
                    {
                        "match": "failed",
                        "value": "#5a1426"
                    },
                    {
                        "match": "running",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "success",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "good",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "normal",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "Reachable",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "Unreachable",
                        "value": "#5a1426"
                    }
                ],
                "range_2": [
                    {
                        "to": 1,
                        "value": "#0d3b2c"
                    },
                    {
                        "from": 1,
                        "to": 3,
                        "value": "#4d3a08"
                    },
                    {
                        "from": 3,
                        "value": "#5a1426"
                    }
                ],
                "range_3": [
                    {
                        "to": 4,
                        "value": "#0d3b2c"
                    },
                    {
                        "from": 4,
                        "to": 9,
                        "value": "#4d3a08"
                    },
                    {
                        "from": 9,
                        "value": "#5a1426"
                    }
                ]
            },
            "eventHandlers": [
                {
                    "type": "drilldown.setToken",
                    "options": {
                        "tokens": [
                            {
                                "token": "network",
                                "key": "row.Network.value"
                            }
                        ]
                    }
                }
            ]
        },
        "viz_11": {
            "type": "splunk.table",
            "dataSources": {
                "primary": "ds_detail"
            },
            "options": {
                "backgroundColor": "transparent",
                "count": 10,
                "headerVisibility": "fixed",
                "fontSize": "small",
                "tableFormat": {
                    "rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBg)",
                    "headerBackgroundColor": "#0b1630",
                    "rowColors": "#eaf2ff",
                    "headerColor": "#9fb1c9"
                },
                "columnFormat": {
                    "Severity": {
                        "rowBackgroundColors": "> table | seriesByName(\"Severity\") | matchValue(statusBg)"
                    }
                }
            },
            "context": {
                "rowBg": [
                    "#0a1328",
                    "#0d1833"
                ],
                "statusBg": [
                    {
                        "match": "Critical",
                        "value": "#5a1426"
                    },
                    {
                        "match": "Degraded",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "Healthy",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "critical",
                        "value": "#5a1426"
                    },
                    {
                        "match": "high",
                        "value": "#5a1426"
                    },
                    {
                        "match": "error",
                        "value": "#5a1426"
                    },
                    {
                        "match": "warning",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "medium",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "stopped",
                        "value": "#5a1426"
                    },
                    {
                        "match": "failed",
                        "value": "#5a1426"
                    },
